// --- APP STATE & INITIALIZATION ---
let currentLang = 'sr';
let activeCategory = 'all';
let searchQuery = '';

document.addEventListener('DOMContentLoaded', () => {
  initLangSwitcher();
  initMobileMenu();
  renderMenu();
  renderReviews();
  setupSearchAndFilters();
  setupSmoothScroll();
});

// --- LANGUAGE SWITCHER ---
function initLangSwitcher() {
  const langBtns = document.querySelectorAll('.lang-btn');
  langBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const lang = btn.dataset.lang;
      if (lang === currentLang) return;

      currentLang = lang;
      
      langBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      updatePageTexts();
      renderMenu();
      renderReviews();
    });
  });
}

function updatePageTexts() {
  const elements = document.querySelectorAll('[data-i18n]');
  elements.forEach(el => {
    const key = el.dataset.i18n;
    if (translations[currentLang] && translations[currentLang][key]) {
      el.textContent = translations[currentLang][key];
    }
  });
}

// --- MOBILE DRAWER MENU ---
function initMobileMenu() {
  const burgerBtn = document.getElementById('burgerBtn');
  const closeDrawer = document.getElementById('closeDrawer');
  const drawer = document.getElementById('mobileDrawer');
  const drawerLinks = document.querySelectorAll('.drawer-link');

  if (burgerBtn && drawer) {
    burgerBtn.addEventListener('click', () => {
      drawer.classList.add('open');
    });
  }

  if (closeDrawer && drawer) {
    closeDrawer.addEventListener('click', () => {
      drawer.classList.remove('open');
    });
  }

  drawerLinks.forEach(link => {
    link.addEventListener('click', () => {
      drawer.classList.remove('open');
    });
  });
}

// --- RENDER REVIEWS ---
function renderReviews() {
  const grid = document.getElementById('reviewsGrid');
  if (!grid) return;

  grid.innerHTML = '';

  reviewsData.forEach(rev => {
    const starsHtml = '★'.repeat(rev.stars) + '☆'.repeat(5 - rev.stars);
    const card = document.createElement('div');
    card.className = 'review-card';
    card.innerHTML = `
      <div>
        <div class="review-stars">${starsHtml}</div>
        <p class="review-text">"${rev.text[currentLang]}"</p>
      </div>
      <div class="review-author">— ${rev.author}</div>
    `;
    grid.appendChild(card);
  });
}

// --- RENDER MENU ---
function renderMenu() {
  const container = document.getElementById('menuContainer');
  if (!container) return;

  container.innerHTML = '';

  const filteredCategories = menuData.filter(cat => {
    if (activeCategory !== 'all' && cat.cat !== activeCategory) return false;
    return true;
  });

  let hasItems = false;

  filteredCategories.forEach(category => {
    const matchingItems = category.items.filter(item => {
      if (!searchQuery) return true;
      const name = item.name[currentLang].toLowerCase();
      const desc = (item.desc || '').toLowerCase();
      return name.includes(searchQuery.toLowerCase()) || desc.includes(searchQuery.toLowerCase());
    });

    if (matchingItems.length === 0) return;

    hasItems = true;

    const catBlock = document.createElement('div');
    catBlock.className = 'category-block';

    const catTitle = document.createElement('h3');
    catTitle.className = 'category-title';
    catTitle.textContent = category.title[currentLang];
    catBlock.appendChild(catTitle);

    const itemsGrid = document.createElement('div');
    itemsGrid.className = 'category-items';

    matchingItems.forEach(item => {
      const itemEl = document.createElement('div');
      itemEl.className = 'menu-item';

      const portionText = item.portion ? `<span class="menu-item-portion">${item.portion}</span>` : '';
      const descText = item.desc ? `<p class="menu-item-desc">${item.desc}</p>` : '';

      itemEl.innerHTML = `
        <div class="menu-item-info">
          <div class="menu-item-name">${item.name[currentLang]}</div>
          ${descText}
        </div>
        <div style="text-align: right;">
          ${portionText}
          <div class="menu-item-price">${item.price}</div>
        </div>
      `;

      itemsGrid.appendChild(itemEl);
    });

    catBlock.appendChild(itemsGrid);
    container.appendChild(catBlock);
  });

  if (!hasItems) {
    const noResultsMsg = {
      sr: "Nema pronađenih jela za vašu pretragu.",
      en: "No menu items match your search.",
      ru: "По вашему запросу ничего не найдено."
    };
    container.innerHTML = `<div style="text-align:center; padding: 40px; color: var(--text-muted); font-size: 1.1rem;">${noResultsMsg[currentLang]}</div>`;
  }
}

// --- SEARCH & CATEGORY FILTERING ---
function setupSearchAndFilters() {
  const tabs = document.querySelectorAll('.tab-btn');
  const searchInput = document.getElementById('menuSearch');

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');

      activeCategory = tab.dataset.cat;
      renderMenu();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value.trim();
      renderMenu();
    });
  }
}

// --- SMOOTH SCROLL ---
function setupSmoothScroll() {
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;

      const targetEl = document.querySelector(targetId);
      if (targetEl) {
        e.preventDefault();
        const headerOffset = 80;
        const elementPosition = targetEl.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

        window.scrollTo({
          top: offsetPosition,
          behavior: "smooth"
        });
      }
    });
  });
}